def query(self, connection, statement: str, values: dict, query_name: str) -> list:
    def execute():
        return [dict(row) for row in connection.execute(text(statement), values).mappings()]
    return self.events.bo_data_execute(
        "db.read", execute, connection=connection, statement=statement, language="sql",
        parameters={"query_name": query_name},
        summarize=lambda rows: {"rows": len(rows), "result": {"count": len(rows)}})

db.write.snippet:
def write(self, connection, statement: str, values: dict, query_name: str) -> int:
    def execute():
        return connection.execute(text(statement), values).rowcount
    return self.events.bo_data_execute(
        "db.write", execute, connection=connection, statement=statement, language="sql",
        parameters={"query_name": query_name},
        summarize=lambda count: {"rows": count, "result": {"count": count}})

