def csrf_user() -> dict:
    user = actor()
    if not user:
        raise BusinessError(401, "login_required")
    candidate = request.headers.get("X-CSRF-Token", request.form.get("csrf", ""))
    if not secrets.compare_digest(digest_token(candidate), user["csrf_hash"]):
        raise BusinessError(403, "csrf_invalid")
    return user

