@web.get("/api/files")
def file_list():
    user = actor()
    if not user:
        if api_request():
            raise BusinessError(401, "login_required")
        return redirect("/login", 303)
    rows = service().list_files(user["id"])
    if api_request():
        return jsonify({"files": rows})
    own = [row for row in rows if row["owner_id"] == user["id"]]
    received = [row for row in rows if row["owner_id"] != user["id"]]
    options = service().users(user["id"])
    return render_page("home.html", user=user, own=own, received=received, options=options,
                       csrf=request.cookies.get("fs_csrf", ""), notice=request.args.get("notice", ""))

