def response_headers(response):
    response.headers["X-Content-Type-Options"] = "nosniff"
    response.headers["Referrer-Policy"] = "same-origin"
    response.headers["Content-Security-Policy"] = "default-src 'self'; style-src 'self'; form-action 'self'; frame-ancestors 'none'"
    if request.path != "/api/stategraph/health":
        response.headers["Cache-Control"] = "no-store"
    if request.args.get("lang") in {"en", "zh-CN"}:
        response.set_cookie("fs_language", request.args["lang"], samesite="Strict")
    return response

