sources.bo_stategraph/query.py:
"""Read-only instance projection shared by public queries, tests, and exports."""


def bo_machine(snapshot: dict) -> dict:
    configurations = []
    journal = []
    for row in snapshot["files"]:
        configurations.append({
            "attempt": row["id"], "phase": row["state"], "state_revision": row["revision"],
            "run_build_id": row["build_id"], "context": row["context"],
            "revision": row["revision"], "activities": {}, "resources": {},
            "journal": [], "state_journal": row["journal"],
        })
        journal.extend({"seq": entry["seq"], "event": entry["event"],
                        "source": entry["before"], "target": entry["after"],
                        "guards": entry["guards"], "attempt": row["id"]}
                       for entry in row["journal"])
    return {"configurations": configurations, "journal": journal}

sources.bo_stategraph/workflow.py:
"""Project adapter for the canonical native flat-state executor."""
import json
from pathlib import Path
from bo_stategraph.driver import BOExecutor


def definition() -> dict:
    path = Path(__file__).resolve().parent / "project.json"
    return json.loads(path.read_text(encoding="utf-8"))["model"]["machine"]


class FileWorkflow:
    def __init__(self, permission: bool):
        self.permission = permission
        self.executor = BOExecutor(definition(), {"permission_granted": self.permission_granted,
                                                  "has_recipients": self.has_recipients})

    def permission_granted(self, context: dict, payload: dict) -> bool:
        return self.permission is True

    def has_recipients(self, context: dict, payload: dict) -> bool:
        return bool(context["recipient_ids"])

    def apply(self, state: str, event: str, context: dict) -> dict:
        return self.executor.step(state, event, context, {})

